MANUAL_RE = re.compile(r'readme|manual|guide|license|template|使用|手冊|說明|教學|範本|範例|sample|^docs?$', re.I)
# developer / build scripts: users of the packaged program never need them
DEV_SCRIPTS = ['*.bat', '*.cmd', '*.sh', '*.ps1', '*.command', 'Makefile', 'Dockerfile',
               '*.toml', '*.cfg', '*.ini.example', 'setup.*', '*.lock']
VERSION_NAMES = ('APP_VERSION', '__version__', 'VERSION')
MAC_RUNNERS = {'arm64': ('macos-latest', 'AppleSilicon'), 'intel': ('macos-15-intel', 'Intel')}


def say(msg):
    print(msg, flush=True)


# ---------------------------------------------------------------- config
def load_config():
    cfg = json.loads(json.dumps(DEFAULTS))
    if CONFIG.exists():
        try:
            cfg.update(json.loads(CONFIG.read_text(encoding='utf-8-sig')))
        except (ValueError, OSError) as e:
            sys.exit('[錯誤] build_config.json 格式錯誤：%s' % e)
    cfg['_說明'] = DEFAULTS['_說明']
    return cfg


def save_config(cfg):
    TOOLS.mkdir(exist_ok=True)
    CONFIG.write_text(json.dumps(cfg, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')


def safe_name(name):
    name = re.sub(r'[\\/:*?"<>|%!^&]+', '', name).strip(' .')
    return name or 'MyApp'


def nice_name(folder):
    # club_ledger_app -> ClubLedger ; non-ASCII folder names are kept as they are
    words = [w for w in re.split(r'[_\-\s]+', folder) if w]
    if words and words[-1].lower() in ('app', 'project', 'src') and len(words) > 1:
        words.pop()
    if all(w.isascii() for w in words):
        return safe_name(''.join(w[:1].upper() + w[1:] for w in words))
    return safe_name(folder)


def safe_version(v):
    v = re.sub(r'[^0-9.]', '', str(v)).strip('.')
    return v if re.match(r'^\d+(\.\d+){0,3}$', v) else '1.0.0'


# ---------------------------------------------------------------- scanning
def local_tops():
    tops = {}
    for p in ROOT.iterdir():
        if p.name in SKIP or p.name.startswith('.'):
            continue
        if p.is_file() and p.suffix == '.py':
            tops[p.stem] = [p]
        elif p.is_dir():
            files = [f for f in p.rglob('*.py')
                     if not SKIP.intersection(f.relative_to(ROOT).parts)]
            if files:
                tops[p.name] = files
    return tops


def module_name(path):
    parts = list(path.relative_to(ROOT).with_suffix('').parts)
    is_pkg = parts[-1] == '__init__'
    if is_pkg:
        parts.pop()
    return '.'.join(parts), is_pkg


def call_name(node):
    f = node.func
    return f.attr if isinstance(f, ast.Attribute) else getattr(f, 'id', '')


def path_strings(tree):
    """String constants used like file paths (call args of path functions,
    path-ish keywords, Path / 'x', or containing a separator / extension)."""
    found = set()

    def add(s):
        if isinstance(s, str) and len(s) < 260:
            found.update(c for c in re.split(r'[\\/]', s) if c and c not in '..')

    for n in ast.walk(tree):
        if isinstance(n, ast.Constant) and isinstance(n.value, str):
            if re.search(r'[\\/]|^[\w\-]+\.\w{1,5}$', n.value):
                add(n.value)
        elif isinstance(n, ast.Call):
            if call_name(n) in PATH_FUNCS:
                for a in n.args:
                    if isinstance(a, ast.Constant):
                        add(a.value)
            for kw in n.keywords:
                if kw.arg and re.search(r'folder|dir|path|url|file|icon', kw.arg) \
                        and isinstance(kw.value, ast.Constant):
                    add(kw.value.value)
        elif isinstance(n, ast.BinOp) and isinstance(n.op, ast.Div) \
                and isinstance(n.right, ast.Constant):
            add(n.right.value)
    return found


def optional_imports(tree):
    """Imports inside try/except ImportError are optional dependencies."""
    names = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Try):
            catches = {getattr(h.type, 'id', '') for h in n.handlers if h.type is not None}
            catches |= {getattr(e, 'id', '') for h in n.handlers
                        if isinstance(h.type, ast.Tuple) for e in h.type.elts}
            if catches & {'ImportError', 'ModuleNotFoundError', 'Exception'} \
                    or any(h.type is None for h in n.handlers):
                for b in n.body:
                    for m in ast.walk(b):
                        if isinstance(m, ast.Import):
                            names.update(a.name.split('.')[0] for a in m.names)
                        elif isinstance(m, ast.ImportFrom) and m.module and not m.level:
                            names.add(m.module.split('.')[0])
    return names


def scan(main_file):
    tops = local_tops()
    entry = (ROOT / main_file).resolve()
    if not entry.is_file():
        sys.exit('[錯誤] 找不到主程式：%s' % main_file)
    queue, seen, used_tops = [entry], set(), set()
    local_mods, external, optional, strings = set(), set(), set(), set()
    versions = []
    while queue:
        f = queue.pop()
        if f in seen:
            continue
        seen.add(f)
        mod, is_pkg = module_name(f)
        if f != entry:
            local_mods.add(mod)
        pkg = mod.split('.') if is_pkg else mod.split('.')[:-1]
        try:
            tree = ast.parse(f.read_text(encoding='utf-8-sig'))
        except (SyntaxError, UnicodeDecodeError, OSError) as e:
            if f == entry:
                sys.exit('[錯誤] 主程式無法解析：%s' % e)
            print('[提示] 略過無法解析的檔案 %s：%s' % (f.relative_to(ROOT), e), file=sys.stderr)
            continue
        strings |= path_strings(tree)
        versions += code_versions(tree, f)
        optional |= optional_imports(tree)
        names = []
        for n in ast.walk(tree):
            if isinstance(n, ast.Import):
                names += [a.name for a in n.names]
            elif isinstance(n, ast.ImportFrom):
                if n.level:
                    base = pkg[:len(pkg) - (n.level - 1)] if n.level > 1 else pkg
                    full = '.'.join(base + ([n.module] if n.module else []))
                else:
                    full = n.module or ''
                if full:
                    names.append(full)
                    names += [full + '.' + a.name for a in n.names if a.name != '*']
        for name in names:
            top = name.split('.')[0]
            if top in tops:
                if top not in used_tops:
                    used_tops.add(top)
                    queue += tops[top]  # whole local package, incl. dynamic imports
            elif top != '__future__':
                external.add(name)
    return {'tops': tops, 'used': used_tops, 'local': local_mods,
            'external': external, 'optional': optional, 'strings': strings,
            'versions': versions}


def code_versions(tree, path):
    """Module-level APP_VERSION / __version__ / VERSION = "x.y.z" in the source."""
    found = []
    for n in tree.body:
        targets = n.targets if isinstance(n, ast.Assign) else [n.target] if isinstance(n, ast.AnnAssign) else []
        value = getattr(n, 'value', None)
        if isinstance(value, ast.Constant) and isinstance(value.value, str):
            for t in targets:
                if isinstance(t, ast.Name) and t.id in VERSION_NAMES:
                    found.append((path.relative_to(ROOT).as_posix(), t.id, value.value))
    return found


def pick_version(cfg, versions):
    """The program's own version (e.g. backend/version.py) wins over the config,
    so the version shown in Windows/macOS file info always matches what the app
    compares against when it checks GitHub Releases for updates."""
    if versions:
        versions = sorted(versions, key=lambda v: (pathlib.Path(v[0]).stem not in ('version', '_version'),
                                                    v[0].count('/'), v[0]))
        path, name, value = versions[0]
        return safe_version(value), '%s 的 %s' % (path, name)
    return safe_version(cfg.get('version', '1.0.0')), 'build_config.json'


def is_module(name):
    try:
        return importlib.util.find_spec(name) is not None
    except (ImportError, ValueError, AttributeError):
        return False


def analyze(cfg):
    s = scan(cfg['main_file'])
    ext_tops = {n.split('.')[0] for n in s['external']}
    ok_tops = {t for t in ext_tops if is_module(t)}
    missing = sorted(ext_tops - ok_tops - s['optional'])
    mods = set(s['local']) | set(cfg.get('hidden_imports') or [])
    mods.update(n for n in s['external']
                if n.split('.')[0] in ok_tops and (n in ok_tops or is_module(n)))
    gui = sorted(ext_tops & GUI_LIBS)
    windowed = cfg.get('windowed', 'auto')
    windowed = bool(gui) if windowed == 'auto' else bool(windowed)
    if cfg.get('data', 'auto') == 'auto':
        data = []
        for p in sorted(ROOT.iterdir()):
            if p.name in SKIP or p.name.startswith('.') or p.suffix in ('.py', '.pyc'):
                continue
            if p.name in s['used'] or p.name == 'requirements.txt':
                continue
            if p.name in s['strings'] or (p.is_dir() and p.name in COMMON_DATA):
                data.append(p.name)
    else:
        data = [d for d in cfg['data'] if (ROOT / d).exists()]
    targets = [cfg['main_file']] + sorted(
        t + '.py' if (ROOT / (t + '.py')).is_file() else t for t in s['used'])
    return {'mods': sorted(mods), 'local': s['local'], 'missing': missing, 'gui': gui,
            'windowed': windowed, 'data': data, 'targets': targets,
            'release': release_files(cfg, s['used'], data),
            'version': pick_version(cfg, s['versions'])}


SENSITIVE = ['.env', '*.env', '*.db', '*.sqlite', '*.sqlite3', '*.log', '*.key', '*.pem',
             '*.p12', '*.pfx', 'id_rsa*', '*secret*', '*credential*']


def release_files(cfg, used, data=()):
    """Items placed NEXT TO the program in the release folder, where users can
    see them (manuals, templates to fill in...). Bundled data is hidden inside.
    'all' (default): the project folder is treated as curated, so everything
    except program code, build/dev folders and sensitive files is included."""
    mode = cfg.get('release_files', 'all')
    if isinstance(mode, list):
        return [r for r in mode if (ROOT / r).exists()]
    skip = set(SENSITIVE) | set(cfg.get('release_exclude') or []) | set(cfg.get('data_exclude') or [])
    out = []
    for p in sorted(ROOT.iterdir()):
        if p.name in SKIP or p.name.startswith('.') or p.name in used \
                or p.suffix in ('.py', '.pyc', '.pyw', '.spec') or p.name.startswith('requirements'):
            continue
        if any(fnmatch.fnmatch(p.name.lower(), s.lower()) for s in skip):
            continue
        if p.is_dir() and ((p / 'pyvenv.cfg').exists() or any(p.rglob('*.py'))):
            continue  # virtual environment or code folder
        if p.is_file() and any(fnmatch.fnmatch(p.name.lower(), s.lower()) for s in DEV_SCRIPTS):
            continue
        if p.name in data and not MANUAL_RE.search(p.name):
            continue  # already bundled inside the program (frontend, assets...)
        if mode == 'names' and not MANUAL_RE.search(p.stem if p.is_file() else p.name):
            continue
        out.append(p.name)
    return out


def mac_arches(cfg):
    a = str(cfg.get('mac_arch', 'both')).lower()
    return ['arm64', 'intel'] if a not in MAC_RUNNERS else [a]


# ---------------------------------------------------------------- commands
def cmd_detect():
    cfg = load_config()
    main = cfg['main_file'] if (ROOT / cfg['main_file']).is_file() else ''
    cands = []
    for p in sorted(ROOT.glob('*.py')):
        try:
            text = p.read_text(encoding='utf-8-sig', errors='replace')
        except OSError:
            continue
        if re.search(r'__name__\s*==\s*[\'"]__main__[\'"]', text) or p.stem in ('main', 'app'):
            cands.append(p.name)
    if not main:
        for pref in ('main.py', 'app.py'):
            if pref in cands:
                main = pref
                break
        else:
            main = cands[0] if len(cands) == 1 else ''
    (pathlib.Path(os.environ.get('PYBUILD_WORK', '.')) / 'candidates.txt').write_text(
        '\n'.join(cands) + '\n', encoding='utf-8')
    say('P_MAIN_FILE=' + main)
    say('P_APP_NAME=' + (cfg['app_name'] or nice_name(ROOT.name)))
    say('P_VERSION=' + safe_version(cfg.get('version', '1.0.0')))
    code_ver = ''
    if main:
        try:
            v, src = pick_version(cfg, scan(main)['versions'])
            code_ver = v if src != 'build_config.json' else ''
        except SystemExit:
            pass
    say('P_CODE_VERSION=' + code_ver)
    say('P_HAS_ICON=' + ('1' if ICON_ICO.is_file() else '0'))
    say('P_ICON_ON=' + ('1' if cfg.get('icon') and ICON_ICO.is_file() else '0'))
    say('P_HAS_CONFIG=' + ('1' if CONFIG.exists() else '0'))


def cmd_save(main, name, icon, version='1.0.0'):
    cfg = load_config()
    cfg.update(main_file=main, app_name=safe_name(name), icon=icon == '1',
               version=safe_version(version))
    save_config(cfg)
    say('P_APP_NAME=' + cfg['app_name'])
    say('P_VERSION=' + cfg['version'])
    # suggested GitHub repository name: ASCII only (Chinese names fall back)
    slug = lambda s: re.sub(r'[^A-Za-z0-9._-]+', '-', s).strip('-.').lower()
    say('P_REPO_NAME=' + (slug(cfg['app_name']) or slug(ROOT.name) or 'my-python-app'))


def cmd_analyze():
    cfg = load_config()
    a = analyze(cfg)
    say('P_MODE=' + ('視窗程式 (偵測到 %s)' % ', '.join(a['gui']) if a['windowed'] and a['gui']
                     else '視窗程式' if a['windowed'] else '主控台程式'))
    say('P_DATA=' + (', '.join(a['data']) or '無'))
    say('P_RELEASE=' + (', '.join(a['release']) or '無'))
    say('P_MISSING=' + ', '.join(a['missing']))
    say('P_MODULES=%d' % len(a['mods']))
    say('P_TARGETS=' + ' '.join(a['targets']))
    say('P_OBFUSCATE=' + ('1' if cfg.get('obfuscate', True) else '0'))
    say('P_ONEFILE=' + ('單一執行檔' if cfg.get('onefile') else '資料夾'))
    say('P_MAC_ARCH=' + ' + '.join(MAC_RUNNERS[x][1] for x in mac_arches(cfg)))
    say('P_VERSION=' + a['version'][0])
    say('P_VERSION_SRC=' + a['version'][1])


def remove(path):
    if path.is_dir() and not path.is_symlink():
        shutil.rmtree(path)
    elif path.exists() or path.is_symlink():
        path.unlink()


def copy_filtered(src, dst, patterns):
    ignore = shutil.ignore_patterns(*patterns)
    if src.is_dir():
        shutil.copytree(src, dst, ignore=ignore, symlinks=True)
    elif not ignore(str(src.parent), [src.name]):
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)


def win_version_file(path, name, version):
    nums = (version.split('.') + ['0'] * 4)[:4]
    t = ', '.join(nums)
    path.write_text(
        "VSVersionInfo(\n"
        "  ffi=FixedFileInfo(filevers=(%s), prodvers=(%s), mask=0x3f, flags=0x0,\n"
        "    OS=0x40004, fileType=0x1, subtype=0x0, date=(0, 0)),\n"
        "  kids=[StringFileInfo([StringTable('040404B0', [\n"
        "    StringStruct('FileDescription', %r), StringStruct('FileVersion', %r),\n"
        "    StringStruct('InternalName', %r), StringStruct('OriginalFilename', %r),\n"
        "    StringStruct('ProductName', %r), StringStruct('ProductVersion', %r)])]),\n"
        "    VarFileInfo([VarStruct('Translation', [1028, 1200])])]\n"
        ")\n" % (t, t, name, version, name, name + '.exe', name, version), encoding='utf-8')


def finish_mac_app(app, name, version, bundle_id):
    """Write name / version into Info.plist, then re-sign: editing the plist
    breaks PyInstaller's ad-hoc signature and Apple Silicon refuses to start it."""
    import plistlib
    plist = app / 'Contents' / 'Info.plist'
    with open(plist, 'rb') as f:
        info = plistlib.load(f)
    info.update(CFBundleName=name, CFBundleDisplayName=name, CFBundleIdentifier=bundle_id,
                CFBundleShortVersionString=version, CFBundleVersion=version,
                NSHighResolutionCapable=True)
    with open(plist, 'wb') as f:
        plistlib.dump(info, f)
    if shutil.which('codesign'):
        subprocess.call(['codesign', '--force', '--deep', '--sign', '-', str(app)])


